import type { Source } from '../types';
import { correlationLift, frechetBounds, independentSweep } from '../lib/analysis';
import { SOURCE_COLOR, pct } from '../lib/format';

function Bar({ p, tone }: { p: number | null; tone: 'dem' | 'muted' }) {
  if (p === null) return null;
  return (
    <span className="mt-1 block h-1 w-full overflow-hidden rounded-full bg-white/10" aria-hidden="true">
      <span className={`block h-full rounded-full ${tone === 'dem' ? 'bg-dem' : 'bg-white/40'}`} style={{ width: `${p * 100}%` }} />
    </span>
  );
}

function SweepValue({ s }: { s: Source }) {
  if (s.sweep !== null && s.sweepEstimated) {
    return (
      <span className="font-semibold text-white" title="Estimated: not published today. Derived from the House and Senate odds using the source's last published split-ticket rate.">
        <span aria-hidden="true">≈</span>{pct(s.sweep, 1)}
        <span className="sr-only"> (estimated)</span>
      </span>
    );
  }
  if (s.sweep !== null) return <span className="font-semibold text-white">{pct(s.sweep, 1)}</span>;
  if (s.house !== null && s.senate !== null) {
    const b = frechetBounds(s.house, s.senate);
    return (
      <span className="text-muted" title="Not published. Range implied by the House and Senate odds.">
        {pct(b.lo)}–{pct(b.hi)}
        <span className="sr-only"> (implied range, not published)</span>
        <span aria-hidden="true">*</span>
      </span>
    );
  }
  return <span className="text-muted">–</span>;
}

function Badge({ s }: { s: Source }) {
  if (s.status === 'error') return <span className="rounded bg-amber-500/15 px-1.5 py-0.5 text-[11px] font-medium text-amber-300">unavailable</span>;
  return s.freshness === 'live' ? (
    <span className="rounded bg-emerald-500/15 px-1.5 py-0.5 text-[11px] font-medium text-emerald-300">live</span>
  ) : (
    <span className="rounded bg-white/10 px-1.5 py-0.5 text-[11px] font-medium whitespace-nowrap text-gray-300">static · {s.asOf}</span>
  );
}

function SourceName({ s }: { s: Source }) {
  return (
    <span className="flex flex-wrap items-center gap-x-2 gap-y-1">
      <span className="h-2.5 w-2.5 shrink-0 rounded-full" style={{ background: SOURCE_COLOR[s.id] }} aria-hidden="true" />
      <a href={s.url} target="_blank" rel="noopener noreferrer" className="font-medium text-gray-100 hover:underline">
        {s.name}
      </a>
      <span className="text-xs text-muted">{s.kind}</span>
      <Badge s={s} />
    </span>
  );
}

const lift = (s: Source) =>
  s.sweep !== null && s.house !== null && s.senate !== null ? correlationLift(s.sweep, s.house, s.senate) : null;
const indep = (s: Source) => (s.house !== null && s.senate !== null ? independentSweep(s.house, s.senate) : null);

/** Per-source comparison of House, Senate and joint probabilities, plus the correlation implied by them. */
export function SourceTable({ sources }: { sources: readonly Source[] }) {
  return (
    <section aria-labelledby="sources-title" className="panel p-5 sm:p-6">
      <h2 id="sources-title" className="text-lg font-semibold text-white">
        By source
      </h2>
      <p className="mt-1 text-sm text-muted">
        “If independent” = House × Senate. Lift &gt; 1× means the sources price both chambers moving together.
      </p>

      {/* Desktop table */}
      <div className="mt-4 hidden md:block">
        <table className="w-full text-left text-sm tabular-nums">
          <thead className="text-xs tracking-wide text-muted uppercase">
            <tr className="border-b border-line">
              <th scope="col" className="py-2 pr-4 font-medium">Source</th>
              <th scope="col" className="w-28 py-2 pr-4 font-medium">House</th>
              <th scope="col" className="w-28 py-2 pr-4 font-medium">Senate</th>
              <th scope="col" className="w-28 py-2 pr-4 font-medium">Sweep</th>
              <th scope="col" className="w-28 py-2 pr-4 font-medium">If independent</th>
              <th scope="col" className="w-20 py-2 font-medium">Lift</th>
            </tr>
          </thead>
          <tbody>
            {sources.map((s) => (
              <tr key={s.id} className="border-b border-line/60 last:border-0">
                <th scope="row" className="py-3 pr-4 font-normal"><SourceName s={s} /></th>
                <td className="py-3 pr-4">{pct(s.house, 1)}<Bar p={s.house} tone="muted" /></td>
                <td className="py-3 pr-4">{pct(s.senate, 1)}<Bar p={s.senate} tone="muted" /></td>
                <td className="py-3 pr-4"><SweepValue s={s} /><Bar p={s.sweep} tone="dem" /></td>
                <td className="py-3 pr-4 text-muted">{pct(indep(s), 1)}</td>
                <td className="py-3">{lift(s) === null ? <span className="text-muted">–</span> : `${lift(s)!.toFixed(2)}×`}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Mobile cards */}
      <ul className="mt-4 grid gap-3 md:hidden">
        {sources.map((s) => (
          <li key={s.id} className="rounded-xl border border-line p-4">
            <SourceName s={s} />
            <dl className="mt-3 grid grid-cols-3 gap-3 text-sm tabular-nums">
              <div><dt className="text-xs text-muted">House</dt><dd>{pct(s.house, 1)}</dd></div>
              <div><dt className="text-xs text-muted">Senate</dt><dd>{pct(s.senate, 1)}</dd></div>
              <div><dt className="text-xs text-muted">Sweep</dt><dd><SweepValue s={s} /></dd></div>
              <div><dt className="text-xs text-muted">If indep.</dt><dd className="text-muted">{pct(indep(s), 1)}</dd></div>
              <div><dt className="text-xs text-muted">Lift</dt><dd>{lift(s) === null ? '–' : `${lift(s)!.toFixed(2)}×`}</dd></div>
            </dl>
          </li>
        ))}
      </ul>
      <p className="mt-3 text-xs text-muted">* Joint value not published; Fréchet bounds from House and Senate odds.</p>
    </section>
  );
}
